14	Future<String> capture(AsyncVoidCallback callback, { int exitCode = 0 }) async {
15	  final StringBuffer buffer = StringBuffer();
16	  final PrintCallback oldPrint = print;
17	  try {
18	    print = (Object line) {
19	      buffer.writeln(line);
20	    };
21	    try {
22	      await callback();
23	      expect(exitCode, 0);
24	    } on ExitException catch (error) {
25	      expect(error.exitCode, exitCode);
26	    }
27	  } finally {
28	    print = oldPrint;
29	  }
30	  return buffer.toString();
31	}
